function minSwaps(arr) {
  const n = arr.length;
  const indexed = arr.map((val, idx) => ({ val, idx }));
  indexed.sort((a, b) => a.val - b.val);
  const visited = new Array(n).fill(false);
  let swaps = 0;
  for (let i = 0; i < n; i++) {
    if (visited[i] || indexed[i].idx === i) continue;
    let cycleSize = 0, j = i;
    while (!visited[j]) {
      visited[j] = true;
      j = indexed[j].idx;
      cycleSize++;
    }
    if (cycleSize > 0) swaps += cycleSize - 1;
  }
  return swaps;
}
